            // Função para lidar com "Selecionar Tudo"
            function handleSelectAll(element) {
                element.on('select2:select', function(e) {
                    if (e.params.data.id === 'all') {
                        let allOptions = element.find('option').map(function() { return $(this).val(); }).get();
                        // Remover 'all' da lista
                        allOptions = allOptions.filter(function(value) { return value !== 'all'; });
